head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
scwin.clickBzProcsNo = "";
scwin.vScrenID = "ULDBNS25400.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 설명       : 일자 조회
 ***********************************************/
scwin.fn_getDate = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ULDSTF41001_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwko.select.getPrevBusiDt";
    dts_getDate.DataID = encodeURI(url);
    dts_getDate.reset();
};


/********************************************** 
 * 설명       : 조회
 ***********************************************/
scwin.fn_Search = function() {
    var vsTabSel = tab_Main.getSelectedTabIndex();
    var vsInOut = "";
    var vsSql = "";
    var voDtsList = null;
    var voGridList = null;
    vsInOut = "BNS_EARNG_RT_RCV_LIST3";
    vsSql = "lds.stf.bnsearng_rt_rcv.select.list3";
    voDtsList = dts_List3;
    voGridList = grd_List3;
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=" + vsInOut;
    url += "&queryId=" + vsSql;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_WORK_DT=" + $c.stf.getObjectValue(edt_SDate);
    voDtsList.DataID = encodeURI(url);
    voDtsList.Reset();
    $c.cm.ShowWin(voGridList);
};


/********************************************** 
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    var vsTabSel = tab_Main.getSelectedTabIndex();
    var voDtsList = null;
    var voGridList = null;
    var excelSheet = '';
    excelSheet = '스트립수익률';
    voDtsList = dts_List3;
    voGridList = grd_List3;
    if (voDtsList.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        var fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_수익률수신.xls";
        voGridList.GridToExcel(excelSheet, "", "8");
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
scwin.gform_onload = function() {
    /********************************************** 
     * 함수명   : gform > onload
     * 설명      : 화면 Onload
     ***********************************************/
    $c.bns.BnsPanelToGroupBox(panel_Top);
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    scwin.fn_getDate();
    $c.stf.setObjectValue(edt_SDate, dts_getDate.getCellData(3, "CALND_DD"));
    edt_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
};
scwin.btn_Search_onclick = function() {
    /********************************************** 
     * 함수명   : btn_Search > onclick
     * 설명      : 조회버튼 클릭
     ***********************************************/
    scwin.fn_Search();
};
scwin.btn_SDate_onclick = function() {
    /********************************************** 
     * 함수명   : btn_SDate > onclick
     * 설명      : 신청일기간 시작일자 달력클릭
     ***********************************************/
    popUpCalendar2(edt_SDate);
};
scwin.btn_Excel_onclick = function() {
    /********************************************** 
     * 함수명   : btn_Excel > onclick
     * 설명      : 엑셀버튼 클릭
     ***********************************************/
    scwin.fn_ExcelDown();
};
scwin.dts_List3_OnLoadError = function() {
    /********************************************** 
     * 함수명   : dts_List3 > OnLoadError
     * 설명      : dts_List3 조회 에러 
     ***********************************************/
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List3_OnLoadCompleted = function(rowcount) {
    /********************************************** 
     * 함수명   : dts_List3 > OnLoadError
     * 설명      : dts_List3 조회 성공
     ***********************************************/
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page3);
    $c.cm.CloseWin(rowcount, grd_List3);
};
